def parse_args(argv: Sequence[str]) -> Matches:
    flags: list[Occurrence] = []
    paths: list[str] = []
    parsing = True
    index = 0

    while index < len(argv):
        token = argv[index]
        index += 1
        if not parsing:
            paths.append(token)
            continue
        if token == "--":
            parsing = False
            continue
        if token.startswith("--"):
            raw = token[2:]
            if "=" in raw:
                name, supplied = raw.split("=", 1)
                spec = LONG_FLAGS.get(name)
                if spec is None:
                    raise OptionError(f"Unknown argument --{name}")
                spelling = f"--{name}"
                if spec.value == "forbidden":
                    raise OptionError(f"Flag {spelling} cannot take a value")
                flags.append(Occurrence(spec, spelling, supplied))
                continue

            spec = LONG_FLAGS.get(raw)
            if spec is None:
                raise OptionError(f"Unknown argument --{raw}")
            spelling = f"--{raw}"
            if spec.value == "forbidden":
                flags.append(Occurrence(spec, spelling, None))
            elif spec.value == "necessary":
                if index >= len(argv):
                    raise _needs_value(spec, spelling)
                flags.append(Occurrence(spec, spelling, argv[index]))
                index += 1
            elif index < len(argv) and spec.choices and argv[index] in spec.choices:
                flags.append(Occurrence(spec, spelling, argv[index]))
                index += 1
            else:
                flags.append(Occurrence(spec, spelling, spec.default))
            continue

        if token.startswith("-") and token != "-":
            raw = token[1:]
            if "=" in raw:
                before, supplied = raw.split("=", 1)
                if not before:
                    paths.append(token)
                    continue
                for char in before[:-1]:
                    spec = SHORT_FLAGS.get(char)
                    if spec is None:
                        raise OptionError(f"Unknown argument -{char}")
                    spelling = f"-{char}"
                    if spec.value == "necessary":
                        raise _needs_value(spec, spelling)
                    value = spec.default if spec.value == "optional" else None
                    flags.append(Occurrence(spec, spelling, value))
                char = before[-1]
                spec = SHORT_FLAGS.get(char)
                if spec is None:
                    raise OptionError(f"Unknown argument -{char}")
                spelling = f"-{char}"
                if spec.value == "forbidden":
                    raise OptionError(f"Flag {spelling} cannot take a value")
                flags.append(Occurrence(spec, spelling, supplied))
                continue

            char_index = 0
            while char_index < len(raw):
                char = raw[char_index]
                spec = SHORT_FLAGS.get(char)
                if spec is None:
                    raise OptionError(f"Unknown argument -{char}")
                spelling = f"-{char}"
                if spec.value == "forbidden":
                    flags.append(Occurrence(spec, spelling, None))
                    char_index += 1
                    continue
                remnants = raw[char_index + 1 :]
                if spec.value == "necessary":
                    if remnants:
                        flags.append(Occurrence(spec, spelling, remnants))
                    elif index < len(argv):
                        flags.append(Occurrence(spec, spelling, argv[index]))
                        index += 1
                    else:
                        raise _needs_value(spec, spelling)
                    break
                if remnants:
                    if spec.choices and remnants in spec.choices:
                        flags.append(Occurrence(spec, spelling, remnants))
                    else:
                        raise OptionError(f"Flag {spelling} cannot take a value")
                    break
                if index < len(argv) and spec.choices and argv[index] in spec.choices:
                    flags.append(Occurrence(spec, spelling, argv[index]))
                    index += 1
                else:
                    flags.append(Occurrence(spec, spelling, spec.default))
                break
            continue

        paths.append(token)

    return Matches(flags, paths)


def _debug(value: str) -> str:
    return json.dumps(value, ensure_ascii=False)


def _bad(spec_name: str, value: str, choices: bool = False) -> OptionError:
    spec = LONG_FLAGS[spec_name]
    suffix = ""
    if choices and spec.choices:
        suffix = f" (choices: {', '.join(spec.choices)})"
    return OptionError(
        f"Option {spec.display} has no {_debug(value)} setting{suffix}"
    )


def _parse_usize(value: str, spec_name: str) -> int:
    if not value:
        reason = "cannot parse integer from empty string"
    elif not value.isascii() or not value.isdigit():
        reason = "invalid digit found in string"
    else:
        number = int(value)
        if number <= (1 << 64) - 1:
            return number
        reason = "number too large to fit in target type"
    spec = LONG_FLAGS[spec_name]
    raise OptionError(
        f"Value {_debug(value)} not valid for option {spec.display}: {reason}"
    )


def _parse_env_usize(value: str, variable: str) -> int:
    if not value:
        reason = "cannot parse integer from empty string"
    elif not value.isascii() or not value.isdigit():
        reason = "invalid digit found in string"
    else:
        number = int(value)
        if number <= (1 << 64) - 1:
            return number
        reason = "number too large to fit in target type"
    raise OptionError(
        f"Value {_debug(value)} not valid for environment variable {variable}: {reason}"
    )


def _duplicate(first: Occurrence, second: Occurrence) -> OptionError:
    if first.spelling == second.spelling:
        return OptionError(f"Flag {first.spelling} was given twice")
    return OptionError(
        f"Flag {first.spelling} conflicts with flag {second.spelling}"
    )


def _strict_duplicates(matches: Matches) -> None:
    ignored = {"help", "version", "all", "grid"}
    for spec in SPECS:
        occurrences = matches.occurrences(spec.long)
        if spec.long not in ignored and len(occurrences) > 1:
            raise _duplicate(occurrences[0], occurrences[1])

    for names in (
        ("binary", "bytes"),
        ("color", "colour"),
    ):
        occurrences = [
            item for item in matches.flags if item.spec.long in names
        ]
        if len(occurrences) > 1:
            raise _duplicate(occurrences[0], occurrences[1])


def _useless_without(option: str, required: str) -> OptionError:
    return OptionError(
        f"Option {LONG_FLAGS[option].display} is useless without option "
        f"{LONG_FLAGS[required].display}"
    )


def _validate_strict(
    matches: Matches,
    view: str,
    tree: bool,
    long_table: bool,
) -> None:
    _strict_duplicates(matches)
    all_count = matches.count("all")
    if all_count > 2:
        spec = LONG_FLAGS["all"]
        raise OptionError(f"Option {spec.display} conflicts with option {spec.display}")

    if not long_table:
        for name in (
            "binary", "bytes", "inode", "links", "header", "blocksize",
            "time", "group", "numeric", "mounts",
        ):
            if matches.has(name):
                raise _useless_without(name, "long")
        if matches.has("git") and not matches.has("no-git"):
            raise _useless_without("git", "long")

    if long_table and view in ("details", "grid-details"):
        if matches.has("across") and not matches.has("grid"):
            raise OptionError(
                f"Option {LONG_FLAGS['across'].display} is useless given option "
                f"{LONG_FLAGS['long'].display}"
            )
        last_view = matches.last_of(("long", "oneline", "grid", "tree"))
        if (
            matches.has("oneline")
            and last_view is not None
            and last_view.spec.long == "long"
        ):
            raise OptionError(
                f"Option {LONG_FLAGS['oneline'].display} is useless given option "
                f"{LONG_FLAGS['long'].display}"
            )

    recurse = matches.has("recurse")
    raw_tree = matches.has("tree")
    as_file = matches.has("treat-dirs-as-files") or matches.has("list-dirs")
    if not recurse and not raw_tree and matches.has("level"):
        raise OptionError(
            f"Option {LONG_FLAGS['level'].display} is useless without options "
            f"{LONG_FLAGS['recurse'].display} or {LONG_FLAGS['tree'].display}"
        )
    if recurse and as_file:
        raise OptionError(
            f"Option {LONG_FLAGS['recurse'].display} conflicts with option "
            f"{LONG_FLAGS['treat-dirs-as-files'].display}"
        )
    if raw_tree and as_file:
        raise OptionError(
            f"Option {LONG_FLAGS['tree'].display} conflicts with option "
            f"{LONG_FLAGS['treat-dirs-as-files'].display}"
        )


