def read_directory(path: Path, options: Options) -> list[Entry]:
    entries: list[Entry] = []
    if options.dot_mode == 2:
        current = Entry.direct(str(path), options.dereference)
        current.name = "."
        current.parented = True
        current.is_all_all = True
        parent = Entry.direct(str(path / ".."), options.dereference)
        parent.name = ".."
        parent.parented = True
        parent.is_all_all = True
        entries.extend((current, parent))

    with os.scandir(path) as iterator:
        names = [item.name for item in iterator]
    for name in names:
        entry = Entry.child(path, name, options.dereference)
        if options.dot_mode == 0 and (
            name.startswith(".")
            or name.startswith("_")
            or bool(entry.attributes & FILE_ATTRIBUTE_HIDDEN)
        ):
            continue
        entries.append(entry)
    return filter_children(entries, options, options.recurse)


def _ignored(name: str, patterns: Iterable[str]) -> bool:
    return any(fnmatch.fnmatchcase(name, pattern) for pattern in patterns)


def filter_argument_entries(entries: list[Entry], options: Options) -> list[Entry]:
    return [entry for entry in entries if not _ignored(entry.name, options.ignore_globs)]


def filter_children(entries: list[Entry], options: Options, is_recurse: bool) -> list[Entry]:
    result = [entry for entry in entries if not _ignored(entry.name, options.ignore_globs)]
    filtered: list[Entry] = []
    for entry in result:
        only_dirs = options.only_dirs
        only_files = options.only_files
        no_links = options.no_symlinks
        show_links = options.show_symlinks
        state = (only_dirs, only_files, no_links, show_links)
        if state in ((True, False, False, False), (True, False, True, False)):
            keep = entry.is_dir
        elif state == (True, False, False, True):
            keep = entry.is_dir or entry.points_to_directory
        elif state == (False, True, False, False):
            keep = True if is_recurse else entry.is_file
        elif state == (False, True, False, True):
            keep = True if is_recurse else (
                entry.is_file or (entry.is_link and not entry.points_to_directory)
            )
        elif state == (False, False, True, False):
            keep = not entry.is_link
        else:
            keep = True
        if keep:
            filtered.append(entry)
    return sort_entries(filtered, options)


_NATURAL_PART = re.compile(r"(\d+)")


def _natural_parts(value: str, ignore_case: bool) -> list[tuple[Any, ...]]:
    if ignore_case:
        value = value.lower()
    pieces: list[tuple[Any, ...]] = []
    for part in _NATURAL_PART.split(value):
        if not part:
            continue
        if part.isdigit():
            # natord orders numerically equal runs with more leading zeroes
            # first: z02, z2, z10.
            pieces.append((0, int(part), -len(part)))
        else:
            pieces.append((1, part))
    return pieces


def _cmp(left: Any, right: Any) -> int:
    return (left > right) - (left < right)


def _natural_compare(left: str, right: str, ignore_case: bool) -> int:
    return _cmp(_natural_parts(left, ignore_case), _natural_parts(right, ignore_case))


def _optional_compare(left: Any | None, right: Any | None) -> int:
    if left is None:
        return 0 if right is None else -1
    if right is None:
        return 1
    return _cmp(left, right)


def _entry_compare(left: Entry, right: Entry, field: str) -> int:
    if field == "none":
        return 0
    if field in ("name", "Name", ".name", ".Name"):
        left_name = left.name[1:] if field.startswith(".") and left.name.startswith(".") else left.name
        right_name = right.name[1:] if field.startswith(".") and right.name.startswith(".") else right.name
        return _natural_compare(left_name, right_name, field in ("name", ".name"))
    if field == "size":
        return _cmp(left.length, right.length)
    if field in ("extension", "Extension"):
        compared = _optional_compare(left.extension, right.extension)
        if compared:
            return compared
        return _natural_compare(left.name, right.name, field == "extension")
    if field in ("modified", "changed", "accessed", "created"):
        return _optional_compare(left.timestamp(field), right.timestamp(field))
    if field == "age":
        return _optional_compare(right.timestamp("modified"), left.timestamp("modified"))
    if field == "type":
        compared = _cmp(left.type_order, right.type_order)
        return compared or _natural_compare(left.name, right.name, False)
    if field == "inode":
        return _cmp(getattr(left.stat, "st_ino", 0), getattr(right.stat, "st_ino", 0))
    return 0


def sort_entries(entries: list[Entry], options: Options) -> list[Entry]:
    result = sorted(entries, key=cmp_to_key(lambda a, b: _entry_compare(a, b, options.sort)))
    if options.reverse:
        result.reverse()
    if options.dirs_first:
        result.sort(key=lambda entry: not entry.points_to_directory)
    elif options.dirs_last:
        result.sort(key=lambda entry: entry.points_to_directory)
    return result
